import os

if not os.path.exists("cartas.txt"):
    print("No hay cartas")
else:
    cartas = []
    with open("cartas.txt", encoding="utf-8") as f:
        for linea in f:
            if not linea.strip():
                continue
            libro, saludo = linea.strip().split(" | ")
            cartas.append((libro, saludo))
    with open("indice.txt", "w", encoding="utf-8") as f:
        for i, (libro, saludo) in enumerate(cartas, 1):
            f.write(f"{i}. {libro} ({len(saludo.split())} palabras)\n")
    print(f"Índice listo: {len(cartas)} cartas")

